      },
      {
        "step": "Analyze filesystem subdirectories",
        "hypothesis": "Growth is caused by non-database files (e.g., logs, diagnostic data, or journal) on the same volume.",
        "how_to_check": "du -sh /var/lib/mongodb/* /var/log/mongodb"
      },
      {
        "step": "Verify WiredTiger internal free space",
        "hypothesis": "The filesystem usage is high but much of it is reusable space within existing data files.",
        "how_to_check": "db.stats().freeStorageSize or db.collection.stats().wiredTiger['block-manager']['file bytes available for reuse']"
